<?php
namespace App\Http\Controllers\Tenant;
use App\Domain\AI\Actions\Models\ActionRun;use App\Domain\AI\Actions\Services\ConfirmActionRunService;use App\Domain\AI\Tenancy\AiTenantBoundary;use App\Http\Controllers\Controller;use App\Http\Requests\Tenant\CloseConversationRequest;use App\Http\Support\AiLaunchpadHttpGate;
final class AiActionController extends Controller
{
 public function show(ActionRun$actionRun,AiLaunchpadHttpGate$gate,AiTenantBoundary$tenants){$gate->ensure(auth()->user());$gate->assertCurrentTenant($actionRun);$actionRun->load(['conversation.agent','confirmer']);$summary=null;if($actionRun->action_key==='zigo.create_shipment_guide'){$input=$actionRun->input;$snapshot=\App\Domain\Shipping\Local\Models\LocalShippingQuoteSnapshot::query()->where('tenant_id',$actionRun->tenant_id)->where('uuid',$input['option_reference']??'')->first();if($snapshot)$summary=['origin'=>$snapshot->origin['postal_code']??'—','destination'=>$snapshot->destination['postal_code']??'—','service'=>$snapshot->service?->name??'—','amount'=>number_format((float)$snapshot->amount,2).' '.$snapshot->currency,'recipient'=>mb_substr((string)($input['recipient']['name']??''),0,1).'***'];}return view('tenant.admin.ai-actions.show',['tenant'=>$tenants->requireTenant(),'actionRun'=>$actionRun,'summary'=>$summary]);}
 public function confirm(CloseConversationRequest$request,ActionRun$actionRun,AiLaunchpadHttpGate$gate,ConfirmActionRunService$service){$gate->ensure($request->user());$gate->assertCurrentTenant($actionRun);try{$service->confirm($request->user(),$actionRun);}catch(\DomainException){return back()->withErrors(['action'=>'La acción ya no está disponible para confirmación.']);}return redirect()->route('tenant.admin.ai-conversations.show',$actionRun->conversation)->with('success','Acción completada.');}
}
